def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """
    Finds a zero of the polynomial with coefficients xs.
    Assumes xs has an even number of coefficients with the largest non-zero coefficient
    guaranteeing a solution.
    """
    def f(x):
        return poly(xs, x)

    # Find any zero in the range -1000 to 1000
    return bisect(f, -1000, 1000)

