def fibfib(n: int):
    """Compute the n-th element of the fibfib number sequence."""
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1

    fib = [0] * (n + 1)
    fib[0], fib[1], fib[2] = 0, 0, 1

    for i in range(3, n + 1):
        fib[i] = fib[i - 1] + fib[i - 2] + fib[i - 3]

