def histogram(test):
    if not test:
        return {}

    # Split the test string into a list of characters
    characters = test.split()

    # Create a dictionary to count occurrences of each character
    count_dict = {}
    for char in characters:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1

    # Determine the maximum count
    max_count = max(count_dict.values())

    # Build a dictionary of characters with the maximum count
    result = {char: count for char, count in count_dict.items() if count == max_count}

    return result

