        magnitude_sum += abs(num)

    return sign_product * magnitude_sum

def tri(n):
    sequence = [1]  # Start with tri(0) = 1, if we use 0 indexing

    for i in range(1, n + 1):
        if i == 1:
            sequence.append(3)
        elif i % 2 == 0:
            sequence.append(1 + i // 2)
        else:
            if i + 1 >= len(sequence):
                next_i_plus_1 = 1 + (i + 1) // 2
            else:
                next_i_plus_1 = sequence[i + 1]
            next_value = sequence[i - 1] + sequence[i - 2] + next_i_plus_1
            sequence.append(next_value)

    return sequence

