def do_algebra(operator, operand):
    # Start with the first operand
    expression_value = operand[0]

    # Iterate over all operators
    for i in range(len(operator)):
        op = operator[i]
        # Use the current operator to combine current operand with the next operand
        if op == '+':
            expression_value += operand[i + 1]
        elif op == '-':
            expression_value -= operand[i + 1]
        elif op == '*':
            expression_value *= operand[i + 1]
        elif op == '//':
            expression_value //= operand[i + 1]
        elif op == '**':
            expression_value **= operand[i + 1]

    # Return the evaluated result
    return expression_value

